 await sembrar(request,'entrada','e2e-09a');await abrir(page,'e2e-09a');await seleccionarEnlace(page,'e1');await tecla(page,'c');await expect(svg(page).getByText('c',{exact:true})).toBeVisible();await expect(opl(page)).toContainText(/si .*Pedido/);await guardado(page);expect(modelo(await leer(request,'e2e-09a')).modelo.enlaces.e1).toMatchObject({modificador:'condicion'});
