 await page.getByRole('button',{name:'Volver a la Biblioteca'}).click();await sembrar(request,'resultados','e2e-09c');await page.reload();await page.getByRole('button',{name:'E2E e2e-09c',exact:true}).click();await cerrarInformes(page);await seleccionarEnlace(page,'e1');const prohibida=page.getByRole('combobox',{name:'Control',exact:true}).getByRole('option',{name:'c',exact:true});expect(await prohibida.evaluate(n=>({opcion:n.tagName,control:n.closest('label')?.control===n.parentElement,selectHabilitado:n.parentElement instanceof HTMLSelectElement&&!n.parentElement.disabled}))).toEqual({opcion:'OPTION',control:true,selectHabilitado:true});await expect(prohibida).toHaveJSProperty('disabled',true);await expect(prohibida).toHaveAttribute('disabled','');await expect(prohibida).toHaveAttribute('title','El control solo puede ser c o e y solo en una entrada canónica.');await captura(page,'09-control');
