async function puntoAbanico(page:Page,id:string){return page.getByLabel(/^Diagrama /).evaluate((root,id)=>{const x=Array.from(root.getElementsByTagName('*')).find(n=>n.getAttribute('data-ref')===`abanico:${id}`);const g=x instanceof SVGGeometryElement?x:x&&Array.from(x.getElementsByTagName('*')).find(n=>n instanceof SVGGeometryElement);if(!(g instanceof SVGGeometryElement))throw new Error('No existe arco de grupo');const t=g.getPointAtLength(g.getTotalLength()/2),p=new DOMPoint(t.x,t.y).matrixTransform(g.getScreenCTM()!);return{x:p.x,y:p.y};},id);}
async function cadena(page:Page){for(const [n,tecla]of [['A','Enter'],['B','Shift+Enter'],['C','Enter'],['D','Enter']]as const){const campo=page.getByRole('textbox',{name:'Nombre siguiente',exact:true});await campo.fill(n);await campo.press(tecla);}await page.getByRole('textbox',{name:'Nombre siguiente',exact:true}).press('Escape');}
