test('T-280 19 SVG genuino, AP13, F9, JSON=GET y B26',async({page,request})=>{
 await sembrar(request,'simple','e2e-19a');await abrir(page,'e2e-19a');const d=await exportar(page),texto=await descargar(page,d.getByRole('button',{name:'OPD SVG · canon-diagrama'}));expect(texto).toContain('@font-face');expect(texto).not.toMatch(/data-ref|data-capa-ui|seleccion-ui/);await d.getByRole('button',{name:'Cerrar diálogo'}).click();await tecla(page,'F9');const comparacion=await svg(page).evaluate((root,t)=>{const actual=root.firstElementChild!.firstElementChild!,doc=new DOMParser().parseFromString(t,'image/svg+xml'),canon=Array.from(doc.documentElement.children).find(x=>x.tagName==='g')!;
 const estructura=(n:Node):unknown=>{if(n.nodeType!==Node.ELEMENT_NODE)return{tipo:n.nodeType,texto:n.nodeValue};const e=n as SVGElement,attrs=Array.from(e.attributes).map(a=>[a.namespaceURI,a.localName,a.name==='style'?(()=>{const css=document.createElement('span').style;css.cssText=a.value;return Array.from(css).sort().map(k=>[k,['letter-spacing','word-spacing'].includes(k)&&/^0(?:px)?$/.test(css.getPropertyValue(k))?'0':css.getPropertyValue(k),css.getPropertyPriority(k)]);})():a.value]).sort((a,b)=>String(a[1]).localeCompare(String(b[1])));return{namespace:e.namespaceURI,tipo:e.localName,attrs,hijos:Array.from(e.childNodes).map(estructura)};};const esperado=estructura(canon),obtenido=estructura(actual),negativos:unknown[]=[];const mutar=(f:(n:Element)=>void)=>{const n=canon.cloneNode(true) as Element;f(n);negativos.push(estructura(n));};mutar(n=>n.setAttribute('id','identidad-distinta'));mutar(n=>n.getElementsByTagName('text')[0]!.textContent='Otro nombre');mutar(n=>n.setAttribute('transform','translate(20 0)'));mutar(n=>n.getElementsByTagName('text')[0]!.setAttribute('style','font-kerning:auto;font-variant-ligatures:none;letter-spacing:0;word-spacing:0'));return{esperado,obtenido,negativos};},texto);expect(comparacion.obtenido).toEqual(comparacion.esperado);for(const negativo of comparacion.negativos)expect(comparacion.obtenido).not.toEqual(negativo);await tecla(page,'F9');await guardado(page);const jsonD=await exportar(page),json=await descargar(page,jsonD.getByRole('button',{name:'Modelo JSON',exact:true}));expect(json).toBe((await leer(request,'e2e-19a')).texto);const html=await descargar(page,jsonD.getByRole('button',{name:'Documento HTML · canon-documento'}));expect(html).toContain('canon-documento');expect(html).toContain('@font-face');expect(html).toContain('Pedido');const md=await descargar(page,jsonD.getByRole('button',{name:'Documento OPL',exact:true}));expect(md).toContain('**Pedido**');expect(md).toContain('*Procesar*');await jsonD.getByRole('button',{name:'Cerrar diálogo'}).click();await seleccionar(page,'Pedido');await tecla(page,'Delete');const bloqueado=await exportar(page);await expect(bloqueado.getByRole('button',{name:'Documento HTML · canon-documento'})).toBeDisabled();await expect(bloqueado.getByText('T-262, A8.2: «Pedido» no aparece en ningún OPD.',{exact:false})).toBeVisible();await expect(bloqueado.getByRole('button',{name:'OPD SVG · canon-diagrama'})).toBeEnabled();expect(modelo(await leer(request,'e2e-19a')).modelo.entidades.o!.nombre).toBe('Pedido');await bloqueado.getByRole('button',{name:'Cerrar diálogo'}).click();
 await page.getByRole('button',{name:'Volver a la Biblioteca'}).click();await expect(page.getByRole('heading',{name:'Biblioteca',exact:true})).toBeVisible();await sembrar(request,'ap13','e2e-19b');await abrir(page,'e2e-19b');await navegar(page,/SD1 Procesar/);const ap=await exportar(page);await expect(ap.getByRole('button',{name:'OPD SVG · canon-diagrama'})).toBeDisabled();const motivosAp=ap.getByText(/^AP-13, R-REF-NTRIV-1\/2:/);await expect(motivosAp).toHaveCount(2);for(const motivo of await motivosAp.all())await expect(motivo).toBeVisible();await captura(page,'19-gates');
});
