test('T-252 24 narrow390, zonas sin scroll y creación mundial real',async({page,request})=>{
 await page.setViewportSize({width:390,height:844});await sembrar(request,'vacio','e2e-24');await abrir(page,'e2e-24');const nav=page.getByRole('navigation',{name:'Zonas del editor'});await expect(nav).toBeVisible();for(const z of ['Propiedades','OPL','Diagnóstico','Lienzo']){const n=nav.getByRole('button',{name:z==='Diagnóstico'?/^Diagnóstico \d+$/:z,exact:true});await expect(n).toBeVisible();await n.click();await expect(n).toHaveAttribute('aria-pressed','true');if(z==='Propiedades')await expect(page.getByRole('heading',{name:'Propiedades',exact:true})).toBeVisible();if(z==='OPL')await expect(opl(page)).toBeVisible();if(z==='Diagnóstico')await expect(page.getByRole('heading',{name:/Diagnóstico/})).toBeVisible();if(z==='Lienzo')await expect(lienzo(page)).toBeVisible();}await nav.getByRole('button',{name:'Lienzo',exact:true}).click();await crear(page,'objeto','Cliente',150,190);await guardado(page);const v=modelo(await leer(request,'e2e-24'));expect(Object.values(v.modelo.entidades).map(c=>c.nombre)).toEqual(['Cliente']);const caja=await cosa(page,'Cliente').boundingBox(),area=await lienzo(page).boundingBox();expect(caja!.x+caja!.width).toBeLessThanOrEqual(area!.x+area!.width+1);expect(caja!.y).toBeGreaterThanOrEqual(area!.y);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(390);await captura(page,'24-narrow');
});
test('T-251 25 multiselección mover3, undo, Decisión y Enlaces N navega',async({page,request})=>{
 await sembrar(request,'basico','e2e-25a');await abrir(page,'e2e-25a');const antes=await leer(request,'e2e-25a');await seleccionar(page,'Pedido');await cosa(page,'Factura').click({modifiers:['Shift']});await cosa(page,'Entregar').click({modifiers:['Shift']});await expect(page.getByText('3 elementos seleccionados.',{exact:true})).toBeVisible();const b=await cosa(page,'Pedido').boundingBox();await page.mouse.move(b!.x+b!.width/2,b!.y+b!.height/2);await page.mouse.down();await page.mouse.move(b!.x+b!.width/2+50,b!.y+b!.height/2+30,{steps:8});await page.mouse.up();await guardado(page);const v=modelo(await leer(request,'e2e-25a')),prev=modelo(antes);for(const id of ['o','a','q']){const x=Object.values(v.modelo.opds.sd!.apariencias).find(x=>x.entidadId===id)!,y=Object.values(prev.modelo.opds.sd!.apariencias).find(x=>x.entidadId===id)!;expect(x.x).not.toBe(y.x);expect(x.y).not.toBe(y.y);}await tecla(page,'Control+z');await guardado(page);expect((await leer(request,'e2e-25a')).texto).toBe(antes.texto);await tecla(page,'Delete');await expect(page.getByRole('dialog',{name:/Confirmar/})).toBeVisible();await captura(page,'25-decision');await page.getByRole('dialog',{name:/Confirmar/}).getByRole('button',{name:'Cancelar',exact:true}).click();await expect(page.getByRole('dialog',{name:'Confirmar quitar de este OPD'})).toBeHidden();await expect(lienzo(page).getByRole('button',{name:'Seleccionar',exact:true})).toBeEnabled();expect((await leer(request,'e2e-25a')).texto).toBe(antes.texto);await tecla(page,'Delete');await page.getByRole('dialog',{name:'Confirmar quitar de este OPD'}).getByRole('button',{name:'Quitar apariciones'}).click();await guardado(page);const quitado=modelo(await leer(request,'e2e-25a'));expect(quitado.modelo.entidades).toEqual(prev.modelo.entidades);expect(quitado.modelo.enlaces).toEqual(prev.modelo.enlaces);expect(quitado.modelo.nextSeq).toBe(prev.modelo.nextSeq);for(const id of ['o','a','q'])expect(Object.values(quitado.modelo.opds.sd!.apariencias).some(x=>x.entidadId===id)).toBe(false);await tecla(page,'Control+z');await guardado(page);expect((await leer(request,'e2e-25a')).texto).toBe(antes.texto);
 await page.getByRole('button',{name:'Volver a la Biblioteca'}).click();await sembrar(request,'refinado','e2e-25b');await page.reload();await page.getByRole('button',{name:'E2E e2e-25b',exact:true}).click();await cerrarInformes(page);await seleccionar(page,'Pedido');await expect(page.getByText('Enlaces (2)',{exact:true})).toBeVisible();const boton=page.getByRole('complementary',{name:'Propiedades y OPL'}).getByRole('button',{name:/Preparar/}).first();await boton.click();await expect(page.getByRole('heading',{name:/consumo/})).toBeVisible();await captura(page,'25-multiple');
});
test('T-010 26 System_Diagram: auto-no-op cadaOPD y revisión original tras undo',async({page,request})=>{
 await abrir(page,'e2e-archivo-System_Diagram');const id='e2e-archivo-System_Diagram',original=await leer(request,id),v=modelo(original);for(const opd of Object.keys(v.modelo.opds)){
  if(new URL(page.url()).hash.split('/')[3]!==opd){await page.getByRole('button',{name:'Elegir OPD'}).click();await page.getByRole('dialog',{name:'Diagramas del modelo'}).getByRole('button',{name:new RegExp(`\\b${String(v.modelo.opds[opd]!.nombre)}\\b`)}).click();}
  const t=await editarOpl(page),canon=await t.inputValue();await expect(page.getByRole('button',{name:'Sin cambios aplicables',exact:true})).toBeDisabled();await t.fill(`${canon}\n**Cliente E2E** es físico.`);await expect(page.getByRole('button',{name:'Aplicar 2 cambios',exact:true})).toBeEnabled();await t.press('Control+Enter');await expect(page.getByRole('button',{name:'Sin cambios aplicables',exact:true})).toBeDisabled();await t.press('Escape');await guardado(page);expect(Object.values(modelo(await leer(request,id)).modelo.entidades).some(c=>c.nombre==='Cliente E2E')).toBe(true);await tecla(page,'Control+z');await guardado(page);const despues=await leer(request,id);expect(despues.rev).toBe(original.rev);expect(despues.texto).toBe(original.texto);
 }await captura(page,'26-system-idempotente');
});

async function arrastrarAEstado(page:Page,ref:string,id:string){const [origen,destino]=await svg(page).evaluate((root,{ref,id})=>{const all=Array.from(root.getElementsByTagName('*'));const asa=all.find(n=>n.getAttribute('data-ui')==='conectar'&&n.getAttribute('data-ref')===ref) as SVGGraphicsElement|undefined;const grupo=all.find(n=>n.getAttribute('data-ref')===`estado:${id}`);const rect=grupo?.getElementsByTagName('rect')[0];if(!asa||!rect)throw new Error('Asa/cápsula reales ausentes');const a=asa.getBBox(),b=rect.getBBox(),o=new DOMPoint(a.x+a.width/2,a.y+a.height/2).matrixTransform(asa.getScreenCTM()!),pts=[.25,.5,.75].flatMap(y=>[.2,.4,.6,.8].map(x=>new DOMPoint(b.x+b.width*x,b.y+b.height*y).matrixTransform(rect.getScreenCTM()!))),d=pts.find(p=>document.elementFromPoint(p.x,p.y)?.closest('[data-ref]')?.getAttribute('data-ref')===`estado:${id}`);if(!d)throw new Error(`La cápsula ${id} no tiene un punto de tinta alcanzable`);return[{x:o.x,y:o.y},{x:d.x,y:d.y}];},{ref,id});await page.mouse.move(origen!.x,origen!.y);await page.mouse.down();await page.mouse.move(destino!.x,destino!.y,{steps:8});const hit=await page.evaluate(p=>{const n=document.elementFromPoint(p.x,p.y);return{ref:n?.closest('[data-ref]')?.getAttribute('data-ref'),tag:n?.tagName,refs:document.elementsFromPoint(p.x,p.y).map(n=>n.closest('[data-ref]')?.getAttribute('data-ref'))};},destino!);expect(hit,`Hit de la cápsula antes de mouseup: ${JSON.stringify(hit)}`).toMatchObject({ref:`estado:${id}`});await page.mouse.up();}

async function accionGuardada(page:Page,id:string,key:string){const put=page.waitForResponse(r=>r.request().method()==='PUT'&&r.url().endsWith(`/api/modelos/${id}`)&&r.status()===200);await tecla(page,key);await put;await guardado(page);}

async function seleccionarEstadoAlcanzable(page:Page,id:string){
 const punto=await svg(page).evaluate((root,id)=>{const g=Array.from(root.getElementsByTagName('*')).find(n=>n.getAttribute('data-ref')===`estado:${id}`),rect=g?.getElementsByTagName('rect')[0];if(!rect)throw Error('Cápsula real ausente');const b=rect.getBBox(),rx=Math.min(Number(rect.getAttribute('rx')??0),b.width/2,b.height/2),m=rect.getScreenCTM()!;const pts=[.1,.25,.5,.75,.9].flatMap(y=>[.2,.4,.6,.8].map(x=>({x:b.x+b.width*x,y:b.y+b.height*y}))).filter(p=>{const dx=Math.max(0,Math.abs(p.x-(b.x+b.width/2))-(b.width/2-rx)),dy=Math.max(0,Math.abs(p.y-(b.y+b.height/2))-(b.height/2-rx));return dx*dx+dy*dy<=rx*rx;}).map(p=>new DOMPoint(p.x,p.y).matrixTransform(m));const p=pts.find(p=>document.elementFromPoint(p.x,p.y)?.closest('[data-ref]')?.getAttribute('data-ref')===`estado:${id}`);if(!p)throw Error('Cápsula sin punto alcanzable');return{x:p.x,y:p.y};},id);
 await page.mouse.move(punto.x,punto.y);const hit=()=>page.evaluate(p=>document.elementFromPoint(p.x,p.y)?.closest('[data-ref]')?.getAttribute('data-ref'),punto);expect(await hit()).toBe(`estado:${id}`);await page.mouse.down();expect(await hit()).toBe(`estado:${id}`);await page.mouse.up();
}
